public class ExamPass {
    public static void main(String[] args) {
        int score = 45;
        boolean perfectAttendance = true;

        if (score >= 50 || (score >= 40 && perfectAttendance)) {
            System.out.println("Passed!");
        } else {
            System.out.println("Failed.");
        }
    }
}
